const tunda = (ms) => new Promise((r) => setTimeout(r, ms));
let sedang = 0;
let puncak = 0;
async function masak(p) {
  sedang++;
  puncak = Math.max(puncak, sedang);
  await tunda(p.ms);
  sedang--;
  if (p.menu === 'Es Krim') throw new Error('Es Krim habis');
  return `${p.menu} siap`;
}
async function prosesSemua(daftar, batas, kerja) {
  const hasil = new Array(daftar.length);
  let berikut = 0;
  async function pekerja() {
    while (berikut < daftar.length) {
      const i = berikut++;
      try {
        hasil[i] = { ok: true, nilai: await kerja(daftar[i]) };
      } catch (e) {
        hasil[i] = { ok: false, nilai: e.message };
      }
    }
  }
  await Promise.all(Array.from({ length: batas }, pekerja));
  return hasil;
}
const pesanan = [
  { menu: 'Kopi', ms: 20 }, { menu: 'Teh', ms: 10 }, { menu: 'Es Krim', ms: 5 },
  { menu: 'Roti', ms: 15 }, { menu: 'Jus', ms: 5 },
];
const hasil = await prosesSemua(pesanan, 2, masak);
console.log(hasil.filter((h) => h.ok).length, 'berhasil');
console.log(hasil.filter((h) => !h.ok).map((h) => h.nilai));
console.log('Paling banyak bersamaan:', puncak);

