const tunda = (ms) => new Promise((r) => setTimeout(r, ms));
async function kali2(n) {
  await tunda(5);
  return n * 2;
}
const hasil = [];
for (const n of [1, 2, 3, 4]) {
  hasil.push(await kali2(n));
}
console.log(hasil);
